function selectedPath(){const source=$('#sim-source').value,destination=$('#sim-destination').value,chosen=$('#sim-relation').value;if(chosen!=='auto'){const index=Number(chosen),relation=model.relationships[index];if(!relation)return null;if(source===relation.source&&destination===relation.target)return[{index,from:source,to:destination,forward:true}];if(source===relation.target&&destination===relation.source)return[{index,from:source,to:destination,forward:false}];return null}const path=findRelationshipPath(model.relationships,source,destination);return path?.length?path:null}
