function renderStats(){if(!model)return;const counts=model.tables.map(table=>model.counts.get(table.name)),complete=counts.every(count=>count?.status==='exact'),rowTotal=complete?counts.reduce((total,count)=>total+count.value,0):null,unknown=counts.filter(count=>count?.status!=='exact').length,ranked=model.tables.filter(table=>model.counts.get(table.name)?.status==='exact').map(table=>({name:table.name,value:model.counts.get(table.name).value})).sort((a,b)=>a.value-b.value),minimum=ranked[0],maximum=ranked.at(-1),average=complete&&model.tables.length?rowTotal/model.tables.length:null;let matched=0,unmatched=0;for(let index=0;index<model.relationships.length;index++){const a=getAnalysis(index);matched+=a.matchedSourceRows;unmatched+=a.unmatchedSourceRows-a.nullKeys}$('#stats-title').textContent=model.database;$('#stats-cards').innerHTML=`<div><b>${model.statistics.tables}</b><span>Total de tablas</span></div><div><b>${complete?rowTotal.toLocaleString('es-MX'):'Incompleto'}</b><span>${complete?'Total general exacto':'Total general no disponible'}</span></div><div><b>${maximum?`${esc(maximum.name)} · ${maximum.value.toLocaleString('es-MX')}`:'—'}</b><span>Mayor conteo exacto</span></div><div><b>${minimum?`${esc(minimum.name)} · ${minimum.value.toLocaleString('es-MX')}`:'—'}</b><span>Menor conteo exacto</span></div><div><b>${average===null?'—':average.toLocaleString('es-MX',{maximumFractionDigits:2})}</b><span>Promedio por tabla${complete?'':' (requiere conteos completos)'}</span></div><div><b>${unknown}</b><span>Conteos no disponibles</span></div><div><b>${matched.toLocaleString('es-MX')}</b><span>Filas origen relacionadas (FK sumadas)</span></div><div><b>${unmatched.toLocaleString('es-MX')}</b><span>Filas FK no nulas sin coincidencia</span></div><div><b>${model.statistics.views}</b><span>Vistas (sin conteo de filas)</span></div>`;$('#stats-table').innerHTML=`<thead><tr><th>Tabla</th><th>Total de registros</th><th>Consulta</th><th>Método</th><th>Precisión / estado</th><th>Columnas</th><th>PK</th><th>FK entrantes</th><th>FK salientes</th></tr></thead><tbody>${model.tables.map(table=>{const c=model.counts.get(table.name),incoming=model.relationships.filter(r=>r.target===table.name).length,outgoing=model.relationships.filter(r=>r.source===table.name).length;return `<tr><td>${esc(table.name)}</td><td>${c?.status==='exact'?c.value.toLocaleString('es-MX'):'—'}</td><td>${esc(c?.queriedAt?new Date(c.queriedAt).toLocaleString('es-MX'):'—')}</td><td>${esc(c?.method||'No disponible')}</td><td>${esc(c?.status==='exact'?'Exacto para las filas del respaldo':c?.reason||'Desconocido')}</td><td>${table.columns.length}</td><td>${esc(table.primaryKey.join('+')||'—')}</td><td>${incoming}</td><td>${outgoing}</td></tr>`}).join('')}</tbody>`}
