function downloadExport(filename,content,type){if(filename==='diccionario.html'&&model){const triggerRows=model.triggers.length?model.triggers.map(trigger=>`<tr><td>${esc(trigger.name)}</td><td>${esc(trigger.table)}</td><td>${esc(trigger.timing)} ${esc(trigger.event)}</td><td>${trigger.affectedTables.length?trigger.affectedTables.map(esc).join(', '):'Sin otras tablas detectadas'}</td></tr>`).join(''):'<tr><td colspan="4">El respaldo no contiene triggers detectables.</td></tr>';const triggerSection=`<section><h2>Triggers definidos (${model.triggers.length})</h2><p>Definiciones del respaldo analizadas estáticamente; no se ejecutan durante la generación del diccionario.</p><div class="scroll"><table><thead><tr><th>Trigger</th><th>Tabla asociada</th><th>Momento y evento</th><th>Tablas afectadas detectadas</th></tr></thead><tbody>${triggerRows}</tbody></table></div></section>`;content=content.replace('</header>',`</header>${triggerSection}`)}if(filename==='informe-validacion.md'&&model){const triggers=model.triggers.map(trigger=>`- ${trigger.name}: ${trigger.timing} ${trigger.event} sobre ${trigger.table}${trigger.affectedTables.length?`; afecta ${trigger.affectedTables.join(', ')}`:''}.`);content+=`\r\n\r\n## Triggers analizados (${model.triggers.length})\r\n\r\nDefiniciones leídas estáticamente del respaldo. No se ejecutaron.\r\n\r\n${triggers.length?triggers.join('\r\n'):'No se detectaron triggers.'}`}const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportAnalysis(format){if(!model)return;const payload=exportPayload();if(format==='json'){downloadExport('dictionary.json',JSON.stringify(payload,null,2),'application/json;charset=utf-8');return}const headers=['Base de datos','Tabla','total_registros_tabla','Estado del conteo','Método de conteo','Fecha y hora del conteo','Triggers de la tabla','Campo','tipo_dato_mysql','descripcion_dato','finalidad_dato','ejemplo_ilustrativo','clasificacion_dato','origen_dato','estado_interpretacion','Longitud','Precisión','Escala','Permite NULL','Valor predeterminado','Autoincremental','Clave primaria','Clave foránea','Referencia FK','Comentario MySQL','¿Qué almacena?','¿Para qué sirve?','Ejemplo ilustrativo','Clasificación','Origen','Estado de interpretación'];const cell=value=>{let text=String(value??'');if(/^[\t\r\n ]*[=+@-]/.test(text))text=`'${text}`;return`"${text.replace(/"/g,'""')}"`};const lines=[headers.map(cell).join(',')];for(const table of payload.tables)for(const column of table.columns)lines.push([payload.database,table.name,column.total_registros_tabla,table.precisionStatus,table.countMethod,table.countedAt,table.triggers.map(trigger=>`${trigger.name} (${trigger.timing} ${trigger.event})${trigger.affectedTables.length?` → ${trigger.affectedTables.join('+')}`:''}`).join('; '),column.name,column.tipo_dato_mysql,column.descripcion_dato,column.finalidad_dato,column.ejemplo_ilustrativo,column.clasificacion_dato,column.origen_dato,column.estado_interpretacion,column.length,column.precision,column.scale,column.nullable?'Sí':'No',column.defaultValue,column.autoIncrement?'Sí':'No',column.primaryKey?'Sí':'No',column.foreignKey?'Sí':'No',column.foreignKeyReference?`${column.foreignKeyReference.table}.${column.foreignKeyReference.columns.join('+')}`:'',column.comment,column.whatItStores,column.purpose,column.illustrativeExample,column.classification,column.origin,column.interpretationState].map(cell).join(','));downloadExport('diccionario-campos.csv','\uFEFF'+lines.join('\r\n'),'text/csv;charset=utf-8')}
$('#export-csv').onclick=()=>exportAnalysis('csv');$('#export-json').onclick=()=>exportAnalysis('json');
function exportDictionaryHtml(){if(!model)return;const payload=exportPayload(),body=payload.tables.map(table=>`<section><h2>${esc(table.name)}</h2><p><b>Total de registros:</b> ${table.recordCount===null?'No disponible':table.recordCount.toLocaleString('es-MX')} · <b>Estado:</b> ${esc(table.precisionStatus)} · <b>Método:</b> ${esc(table.countMethod||'No disponible')} · <b>Consulta:</b> ${esc(table.countedAt?new Date(table.countedAt).toLocaleString('es-MX'):'—')}</p><div class="scroll"><table><thead><tr><th>Nombre</th><th>Tipo de dato MySQL</th><th>Descripción del dato</th><th>Finalidad del dato</th><th>Ejemplo ilustrativo</th><th>Clasificación</th><th>Origen</th><th>Estado de interpretación</th><th>NULL</th><th>Predeterminado</th><th>PK</th><th>FK</th></tr></thead><tbody>${table.columns.map(column=>`<tr><td>${esc(column.name)}</td><td><code>${esc(column.tipo_dato_mysql)}</code></td><td>${esc(column.descripcion_dato)}</td><td>${esc(column.finalidad_dato)}</td><td>${esc(column.ejemplo_ilustrativo)}</td><td>${esc(column.clasificacion_dato)}</td><td>${esc(column.origen_dato)}</td><td>${esc(column.estado_interpretacion)}</td><td>${column.nullable?'Sí':'No'}</td><td>${column.defaultValue===null?'—':esc(column.defaultValue)}</td><td>${column.primaryKey?'Sí':'No'}</td><td>${column.foreignKey?(column.foreignKeyReference?`${esc(column.foreignKeyReference.table)}.${esc(column.foreignKeyReference.columns.join('+'))}`:'Sí'):'No'}</td></tr>`).join('')}</tbody></table></div></section>`).join('');const html=`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diccionario de datos · ${esc(payload.database)}</title><style>body{font:14px/1.5 system-ui,sans-serif;margin:0;padding:32px;color:#263143;background:#f3f6f9}main{max-width:1400px;margin:auto}h1{margin-bottom:4px}header p{color:#58677a}section{margin:24px 0;padding:20px;background:white;border:1px solid #d8dee7;border-radius:10px}h2{margin-top:0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:9px;text-align:left;vertical-align:top;border-bottom:1px solid #e0e5eb}th{position:sticky;top:0;background:#eaf0f4;white-space:nowrap}td{min-width:105px}td:nth-child(3),td:nth-child(4){min-width:230px}code{white-space:nowrap}footer{color:#637186;font-size:12px;margin:24px 0}</style></head><body><main><header><h1>Diccionario de datos · ${esc(payload.database)}</h1><p>Exportado ${esc(new Date(payload.exportedAt).toLocaleString('es-MX'))}. Las descripciones se generan a partir del esquema analizado; los ejemplos son ilustrativos y no se extraen de registros.</p><p>Conteos: ${payload.summary.exactCountTables} exactos · ${payload.summary.estimatedCountTables} estimados · ${payload.summary.unavailableCountTables} no disponibles. Se cuentan filas INSERT legibles del respaldo mediante análisis estático de solo lectura; no equivalen a conteos de una instancia MySQL activa.</p></header>${body}<footer>Las finalidades que no se pueden determinar con la información del esquema aparecen como pendientes de confirmar.</footer></main></body></html>`;downloadExport('diccionario.html',html,'text/html;charset=utf-8')}
function exportValidationReport(){if(!model)return;const payload=exportPayload(),lines=[`# Informe de validación · ${payload.database}`,'',`- Generado: ${new Date(payload.exportedAt).toLocaleString('es-MX')}.`,`- Tablas analizadas: ${payload.summary.tableCount}.`,`- Conteos exactos: ${payload.summary.exactCountTables}.`,`- Conteos estimados: ${payload.summary.estimatedCountTables}.`,`- Conteos no disponibles: ${payload.summary.unavailableCountTables}.`,`- Conteo global: ${payload.summary.totalIsComplete?payload.summary.totalRecords.toLocaleString('es-MX')+' registros exactos':'no disponible porque existen tablas sin conteo exacto'}.`,'',`Alcance: ${payload.countScope}`,'','## Detalle por tabla','','| Tabla | Conteo | Estado | Método | Fecha de consulta | Nota |','|---|---:|---|---|---|---|',...payload.tables.map(table=>`| ${table.name.replace(/\|/g,'\\|')} | ${table.recordCount===null?'—':table.recordCount} | ${table.precisionStatus} | ${(table.countMethod||'No disponible').replace(/\|/g,'\\|')} | ${table.countedAt||'—'} | ${(table.countNote||'').replace(/\|/g,'\\|')} |`),'','No se usaron estimaciones como conteos exactos. Los conteos corresponden a INSERT legibles del respaldo, no a una instancia MySQL activa.'];downloadExport('informe-validacion.md',lines.join('\r\n'),'text/markdown;charset=utf-8')}
$('#export-report').onclick=exportValidationReport;
$('#export-html').onclick=exportDictionaryHtml;
